int fd[2]; // fd[0]: Read end, fd[1]: Write end
pipe(fd);

if (fork() == 0) {
    // Child Process (Writer)
    close(fd[0]);
    char* msg = "DATA";
    write(fd[1], msg, 5);
    close(fd[1]);
    exit(0);
} else {
    // Parent Process (Reader)
    char buffer[10];
    close(fd[1]);
    read(fd[0], buffer, 5);
    // buffer now contains "DATA"
    close(fd[0]);
    wait(NULL); // Wait for child
}
